CREATE VIEW "Z_TEST_PRODUCTION_20250925"."B1_SnBOpenQtyViewAlloc" ( "DocType", "DocEntry", "DocLine", "DocSubLine", "ManagedBy", "ItemCode", "SysNumber", "LocCode", "Quantity" ) AS SELECT T0."AllocateTp" AS "DocType", T0."AllocatEnt" AS "DocEntry", T0."AllocateLn" AS "DocLine", T0."AppSubLine" AS "DocSubLine", T0."ManagedBy" AS "ManagedBy", T0."ItemCode" AS "ItemCode", T0."SysNumber" AS "SysNumber", T0."LocCode" AS "LocCode", SUM(T0."AllocQty") AS "Quantity" FROM  "Z_TEST_PRODUCTION_20250925"."B1_SnBOpenQtyInnerViewAlloc" T0  GROUP BY T0."AllocateTp", T0."AllocatEnt", T0."AllocateLn", T0."AppSubLine", T0."ManagedBy", T0."ItemCode", T0."SysNumber", T0."LocCode" HAVING SUM(T0."AllocQty") <> (0 ) WITH READ ONLY